import {IonApp,IonPage,IonHeader,IonToolbar,IonTitle,IonContent,IonCheckbox} from "@ionic/react";
import {useState} from "react";
export default function App(){const [ready,setReady]=useState(false);return <IonApp><IonPage><IonHeader><IonToolbar><IonTitle>Reading club</IonTitle></IonToolbar></IonHeader><IonContent className="ion-padding"><IonCheckbox checked={ready} onIonChange={event=>setReady(event.detail.checked)}>Ready to read</IonCheckbox><p>{ready?"Ready":"Not ready yet"}</p></IonContent></IonPage></IonApp>;}
